using System.IO;using System.Linq;using System.Collections.Generic;using UnityEngine;using UnityEditor;
[InitializeOnLoad]public static class BeachFarChairSupports{static BeachFarChairSupports(){EditorApplication.update+=Poll;}static void Poll(){if(EditorApplication.isCompiling||!File.Exists("BeachFarChairSupports.request"))return;File.Delete("BeachFarChairSupports.request");foreach(string name in new[]{"Blue","Coral","Green"}){var m=AssetDatabase.LoadAssetAtPath<Mesh>("Assets/Scenes/Oasis/SouthBeach/BeachDetails/"+name+" furniture far v2.asset");var p=m.vertices.ToList();var uv=m.uv.ToList();var c=m.colors.ToList();var ids=m.triangles.ToList();foreach(float cx in new[]{-1.18f,1.18f})foreach(float x in new[]{cx-.25f,cx+.25f})foreach(float z in new[]{-.98f,.10f}){var v=new Vector3[8];for(int k=0;k<8;k++)v[k]=new Vector3(x+(k%2==0?-.04f:.04f),(k&2)==0?.01f:.46f,z+((k&4)==0?-.04f:.04f));foreach(var f in new[]{new[]{0,2,3,1},new[]{4,5,7,6},new[]{0,1,5,4},new[]{2,6,7,3},new[]{0,4,6,2},new[]{1,3,7,5}})foreach(int k in new[]{f[0],f[1],f[2],f[0],f[2],f[3]}){ids.Add(p.Count);p.Add(v[k]);uv.Add(new Vector2(.205f+v[k].x*.004f,.32f+v[k].y*.04f));c.Add(Color.white);}}m.Clear();m.SetVertices(p);m.SetUVs(0,uv);m.SetColors(c);m.SetTriangles(ids,0);m.RecalculateNormals();m.RecalculateBounds();m.RecalculateTangents();m.Optimize();EditorUtility.SetDirty(m);}AssetDatabase.SaveAssets();}}
